import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"About","description":"","frontmatter":{},"headers":[],"relativePath":"en/about.md","filePath":"en/about.md"}`),a={name:`en/about.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to “About”">​</a></h1><p>Zotero PDF2zh is a plugin for translating PDFs using PDF2zh and PDF2zh_next in Zotero.</p><h2 id="project-introduction" tabindex="-1">Project Introduction <a class="header-anchor" href="#project-introduction" aria-label="Permalink to “Project Introduction”">​</a></h2><p>This plugin perfectly preserves original formatting, supports multiple translation engines and services, allowing you to easily translate PDF literature in Zotero.</p><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to “Core Features”">​</a></h2><ul><li>🚀 Dual engine support (PDF2zh and PDF2zh_next)</li><li>📄 Perfectly preserve original formatting, formulas, and layout</li><li>🔄 Multiple translation modes (translate, crop, compare, etc.)</li><li>🌐 Support multiple translation services (OpenAI, DeepSeek, Zhipu, etc.)</li><li>⚙️ Flexible configuration options</li><li>🆓 Built-in free translation service</li><li>📦 Automatic update functionality</li><li>🐳 Docker deployment support</li></ul><h2 id="supported-zotero-versions" tabindex="-1">Supported Zotero Versions <a class="header-anchor" href="#supported-zotero-versions" aria-label="Permalink to “Supported Zotero Versions”">​</a></h2><p><a href="https://www.zotero.org" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/Zotero-7-red?style=flat-square&amp;logo=zotero&amp;logoColor=CC2936" alt="Zotero 7"></a><a href="https://www.zotero.org/support/beta_builds" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/Zotero-8-orange?style=flat-square&amp;logo=zotero&amp;logoColor=CC2936" alt="Zotero 8"></a><a href="https://www.zotero.org/support/beta_builds" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/Zotero-9-yellow?style=flat-square&amp;logo=zotero&amp;logoColor=CC2936" alt="Zotero 9"></a><a href="https://www.zotero.org/support/beta_builds" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/Zotero-10-green?style=flat-square&amp;logo=zotero&amp;logoColor=CC2936" alt="Zotero 10"></a></p><h2 id="project-links" tabindex="-1">Project Links <a class="header-anchor" href="#project-links" aria-label="Permalink to “Project Links”">​</a></h2><ul><li><a href="https://github.com/guaguastandup/zotero-pdf2zh" target="_blank" rel="noreferrer">GitHub Repository</a></li><li><a href="https://github.com/guaguastandup/zotero-pdf2zh/releases" target="_blank" rel="noreferrer">Plugin Download</a></li><li><a href="https://github.com/guaguastandup/zotero-pdf2zh/issues" target="_blank" rel="noreferrer">Issue Tracker</a></li></ul><h2 id="acknowledgments" tabindex="-1">Acknowledgments <a class="header-anchor" href="#acknowledgments" aria-label="Permalink to “Acknowledgments”">​</a></h2><p>This project is based on the following excellent open-source projects:</p><ul><li><a href="https://github.com/Byaidu" target="_blank" rel="noreferrer">@Byaidu</a> - <a href="https://github.com/Byaidu/PDFMathTranslate" target="_blank" rel="noreferrer">PDF2zh</a></li><li><a href="https://github.com/awwaawwa" target="_blank" rel="noreferrer">@awwaawwa</a> - <a href="https://github.com/PDFMathTranslate/PDFMathTranslate-next" target="_blank" rel="noreferrer">PDF2zh_next</a></li><li><a href="https://github.com/windingwind" target="_blank" rel="noreferrer">@windingwind</a> - <a href="https://github.com/windingwind/zotero-plugin-template" target="_blank" rel="noreferrer">zotero-plugin-template</a></li><li><a href="https://immersivetranslate.com" target="_blank" rel="noreferrer">沉浸式翻译</a> - Sponsoring monthly Pro membership redemption codes for active contributors</li></ul><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to “Contributors”">​</a></h2><p>Thanks to all contributors for their dedication!!</p><a href="https://github.com/guaguastandup/zotero-pdf2zh/graphs/contributors"><img src="https://contrib.rocks/image?repo=guaguastandup/zotero-pdf2zh" alt="Contributors"></a><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to “License”">​</a></h2><p><a href="https://github.com/guaguastandup/zotero-pdf2zh/blob/main/LICENSE" target="_blank" rel="noreferrer"><img src="https://img.shields.io/github/license/guaguastandup/zotero-pdf2zh" alt="License"></a></p><p>Released under MIT License.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><ul><li>QQ Group: Group 5: 1064435415 (join code: see the official GitHub/Gitee page)</li><li>GitHub Issues: <a href="https://github.com/guaguastandup/zotero-pdf2zh/issues" target="_blank" rel="noreferrer">Submit Issue</a></li></ul><h2 id="star-history" tabindex="-1">Star History <a class="header-anchor" href="#star-history" aria-label="Permalink to “Star History”">​</a></h2><p><a href="https://star-history.com/#guaguastandup/zotero-pdf2zh&amp;Date" target="_blank" rel="noreferrer"><img src="https://api.star-history.com/svg?repos=guaguastandup/zotero-pdf2zh&amp;type=Date" alt="Star History Chart"></a></p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};